actions.script:
import org.moqui.impl.llm.SkillIndex
def skill = ec.entity.find("moqui.llm.LlmSkill").condition("skillId", skillId).forUpdate(true).useCache(false).one()
if (skill == null) { ec.message.addError("Skill ${skillId} not found"); return }
if (SkillIndex.isShippedName(ec, skill.name)) {
    ec.message.addError("A shipped skill file named ${skill.name} owns that name. Edit the file, not this row.")
    return
}
if (riskId && !(riskId in ['LskReversible', 'LskConfirm', 'LskIrreversible'])) {
    ec.message.addError("Unknown risk ${riskId}"); return
}
skill.statusId = "LsksActive"
skill.provenanceId = "LskpHuman"
if (riskId) skill.riskId = riskId
skill.speaker = ec.user.username
skill.warrant = "Approved by ${ec.user.username} on ${ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd HH:mm')}".toString()
skill.update()

def skill = ec.entity.find("moqui.llm.LlmSkill").condition("skillId", skillId).forUpdate(true).useCache(false).one()
if (skill == null) { ec.message.addError("Skill ${skillId} not found"); return }
skill.statusId = "LsksRejected"
skill.update()

def skill = ec.entity.find("moqui.llm.LlmSkill").condition("skillId", skillId).forUpdate(true).useCache(false).one()
if (skill == null) { ec.message.addError("Skill ${skillId} not found"); return }
skill.statusId = "LsksDeprecated"
skill.update()

if (oldSkillId == newSkillId) { ec.message.addError("A skill cannot supersede itself"); return }
def oldSkill = ec.entity.find("moqui.llm.LlmSkill").condition("skillId", oldSkillId).forUpdate(true).useCache(false).one()
def newSkill = ec.entity.find("moqui.llm.LlmSkill").condition("skillId", newSkillId).forUpdate(true).useCache(false).one()
if (oldSkill == null || newSkill == null) { ec.message.addError("Skill not found"); return }
oldSkill.statusId = "LsksSuperseded"
oldSkill.update()
newSkill.supersededSkillId = oldSkillId
newSkill.update()

import org.moqui.impl.llm.SkillIndex
def skill = ec.entity.find("moqui.llm.LlmSkill").condition("skillId", skillId).forUpdate(true).useCache(false).one()
if (skill == null) { ec.message.addError("Skill ${skillId} not found"); return }
if (SkillIndex.isShippedName(ec, skill.name)) {
    ec.message.addError("A shipped skill file named ${skill.name} owns that name. Edit the file, not this row.")
    return
}
if (riskId && !(riskId in ['LskReversible', 'LskConfirm', 'LskIrreversible'])) {
    ec.message.addError("Unknown risk ${riskId}"); return
}
if (kind && !(kind in ['procedure', 'reference'])) { ec.message.addError("Unknown kind ${kind}"); return }
if (kind) skill.kind = kind
if (body != null && !body.trim()) { ec.message.addError("A skill needs a body"); return }
if (title != null) skill.title = title
if (description != null) skill.description = description
if (summary != null) skill.summary = summary ?: null
if (body != null) skill.body = body
if (riskId) skill.riskId = riskId
skill.version = ((skill.version ?: 0) as Integer) + 1
skill.update()
if (body != null && body.length() > SkillIndex.BODY_WARN_CHARS)
    ec.message.addMessage("Body is ${body.length()} characters. Skills over ${SkillIndex.BODY_WARN_CHARS} are costly to inject.", "warning")

if (!(statusId in ['LsksActive', 'LsksProposed', 'LsksRejected', 'LsksDeprecated'])) {
    ec.message.addError("Unknown lesson status ${statusId}"); return
}
def lesson = ec.entity.find("moqui.llm.LlmLesson").condition("lessonId", lessonId).forUpdate(true).useCache(false).one()
if (lesson == null) { ec.message.addError("Lesson ${lessonId} not found"); return }
lesson.statusId = statusId
lesson.update()

def conv = ec.entity.find("moqui.llm.LlmConversation").condition("conversationId", conversationId).forUpdate(true).useCache(false).one()
if (conv == null) { ec.message.addError("Conversation ${conversationId} not found"); return }
if (conv.statusId == "LlmcsStreaming") {
    ec.message.addError("Conversation is Streaming. Cancel it first."); return
}
callLogsRemoved = ec.entity.find("moqui.llm.LlmCallLog").condition("conversationId", conversationId).deleteAll()
messagesRemoved = ec.entity.find("moqui.llm.LlmMessage").condition("conversationId", conversationId).deleteAll()
conv.delete()
